{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Subject to appropriation, the department must allocate each LEA sufficient funds to employ one full-time licensed professional school counselor at each high school enrolling at least 600 students in grades 10–12.",
      "importance": "core",
      "section": "SECTION 1(a)(1)",
      "source_quote": "Subject to appropriation, the department shall allocate to each LEA"
    },
    {
      "id": "P2",
      "proposition": "An LEA employing one or more part-time licensed professional school counselors at a high school enrolling at least 600 students in grades 10–12 may use the allocated funds to convert a part-time counselor to full-time employment; that conversion satisfies subsection (b)'s employment requirement.",
      "importance": "supporting",
      "section": "SECTION 1(a)(2)",
      "source_quote": "satisfies the requirement in subsection (b)."
    },
    {
      "id": "P3",
      "proposition": "An LEA employing one full-time licensed professional school counselor for every 250 student members may use the allocated funds to supplant its cost of employing the number of full-time counselors required to meet that ratio.",
      "importance": "core",
      "section": "SECTION 1(a)(3)",
      "source_quote": "to supplant the"
    },
    {
      "id": "P4",
      "proposition": "Each LEA must employ one full-time licensed professional school counselor at each high school for which it receives funding under the new section. An LEA employing one full-time licensed professional school counselor for every 250 student members is not required to employ additional full-time counselor positions beyond the number needed to meet that ratio.",
      "importance": "core",
      "section": "SECTION 1(b)",
      "source_quote": "beyond the number required for the LEA to meet the specified ratio."
    },
    {
      "id": "P5",
      "proposition": "Funds allocated to an LEA under the new section are additional to its TISA funding.",
      "importance": "supporting",
      "section": "SECTION 1(c)",
      "source_quote": "funds allocated to the LEA for purposes of the TISA."
    },
    {
      "id": "P6",
      "proposition": "The state board may, in consultation with the department, promulgate rules establishing roles and responsibilities for full-time licensed professional school counselors funded under the new section that exceed those required by § 49-6-303.",
      "importance": "core",
      "section": "SECTION 1(d)(1)",
      "source_quote": "that exceed those required of school counselors in § 49-6-303."
    },
    {
      "id": "P7",
      "proposition": "The state board must, in consultation with the department, promulgate rules establishing how much time each full-time licensed professional school counselor funded under the new section must dedicate to providing high school students the preventative and developmental counseling services required by § 49-6-303(b), one or more counseling and guidance services listed in § 49-5-302(b), and services needed to comply with additional roles and responsibilities established under subdivision (d)(1). Each full-time licensed professional school counselor must dedicate at least 70% of the counselor's time to working directly with high school students.",
      "importance": "core",
      "section": "SECTION 1(d)(2)",
      "source_quote": "must dedicate at least seventy percent (70%) of"
    },
    {
      "id": "P8",
      "proposition": "The act does not appropriate funds, and funds may not be obligated or expended under it unless specifically appropriated by the general assembly.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "unless the funds are specifically appropriated by the general"
    },
    {
      "id": "P9",
      "proposition": "For rulemaking purposes, the act takes effect upon becoming law.",
      "importance": "supporting",
      "section": "SECTION 3",
      "source_quote": "For purposes of promulgating rules, this act takes effect upon becoming a"
    },
    {
      "id": "P10",
      "proposition": "For all other purposes, the act takes effect July 1, 2025, and applies to the 2025–2026 school year and each subsequent school year.",
      "importance": "supporting",
      "section": "SECTION 3",
      "source_quote": "For all other purposes, this act takes effect July 1, 2025,"
    }
  ]
}
